const response = ($input.first().json || {});
const data = (response.data || {});
const organic = Array.isArray(data.organic) ? data.organic : [];
const peopleAlsoAsk = Array.isArray(data.peopleAlsoAsk) ? data.peopleAlsoAsk : [];
const relatedSearches = Array.isArray(data.relatedSearches) ? data.relatedSearches : [];

return [{
  json: {
    engine: 'google',
    ok: response.code === 0 && organic.length > 0,
    message: response.msg || response.message || '',
    organic,
    peopleAlsoAsk,
    relatedSearches
  }
}];

const response = ($input.first().json || {});
const data = (response.data || {});
const organic = Array.isArray(data.organic) ? data.organic : [];
const peopleAlsoAsk = Array.isArray(data.peopleAlsoAsk) ? data.peopleAlsoAsk : [];
const relatedSearches = Array.isArray(data.relatedSearches) ? data.relatedSearches : [];

return [{
  json: {
    engine: 'bing',
    ok: response.code === 0 && organic.length > 0,
    message: response.msg || response.message || '',
    organic,
    peopleAlsoAsk,
    relatedSearches
  }
}];

const config = $('Set research config').first().json;
const responses = $input.all().map(item => item.json);
const queryTokens = String(config.query || '')
  .toLowerCase()
  .split(/[^a-z0-9]+/)
  .filter(token => token.length > 2);

const byUrl = new Map();
const questions = [];
const relatedSearches = [];
const engineErrors = [];

for (const response of responses) {
  if (!response.ok) {
    engineErrors.push({ engine: response.engine, message: response.message || 'No organic results' });
  }

  for (const item of response.peopleAlsoAsk || []) {
    const question = item.question || item.title || item;
    if (typeof question === 'string' && question.trim()) questions.push(question.trim());
  }

  for (const item of response.relatedSearches || []) {
    const term = item.query || item.title || item;
    if (typeof term === 'string' && term.trim()) relatedSearches.push(term.trim());
  }

  for (const result of response.organic || []) {
    const rawUrl = result.link || result.url;
    if (!rawUrl || !/^https?:\/\//i.test(rawUrl)) continue;

    let parsed;
    try {
      parsed = new URL(rawUrl);
    } catch {
      continue;
    }

    if (/^(localhost|127\.|0\.)/i.test(parsed.hostname)) continue;
    if (/\/(login|signin|account)(\/|$)/i.test(parsed.pathname)) continue;
    parsed.hash = '';
    ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'gclid', 'fbclid']
      .forEach(key => parsed.searchParams.delete(key));

    const normalizedUrl = parsed.toString();
    const title = String(result.title || normalizedUrl).trim();
    const snippet = String(result.snippet || result.description || '').trim();
    const position = Number(result.position || result.rank || 99);
    const text = (title + ' ' + snippet).toLowerCase();
    const tokenMatches = queryTokens.filter(token => text.includes(token)).length;
    const score = Math.max(0, 35 - position) + tokenMatches * 4 + (parsed.protocol === 'https:' ? 2 : 0);

    const existing = byUrl.get(normalizedUrl);
    if (existing) {
      existing.engines = [...new Set([...existing.engines, response.engine])];
      existing.bestPosition = Math.min(existing.bestPosition, position);
      existing.score = Math.max(existing.score, score) + 18;
      if (!existing.snippet && snippet) existing.snippet = snippet;
      continue;
    }

    byUrl.set(normalizedUrl, {
      title,
      url: normalizedUrl,
      hostname: parsed.hostname.replace(/^www\./, ''),
      snippet,
      engines: [response.engine],
      bestPosition: position,
      score
    });
  }
}

const requested = Math.min(Math.max(Number(config.maxSources || 4), 2), 6);
const domainCap = Math.min(Math.max(Number(config.maxPerDomain || 1), 1), 2);
const domainCounts = new Map();
const selected = [];

for (const candidate of [...byUrl.values()].sort((a, b) => b.score - a.score || a.bestPosition - b.bestPosition)) {
  const count = domainCounts.get(candidate.hostname) || 0;
  if (count >= domainCap) continue;
  domainCounts.set(candidate.hostname, count + 1);
  selected.push(candidate);
  if (selected.length >= requested) break;
}

if (selected.length === 0) {
  throw new Error('Neither search engine produced an extractable source URL. Review the query, credential, and API responses.');
}

const researchContext = {
  query: config.query,
  country: config.country,
  language: config.language,
  generatedAt: new Date().toISOString(),
  searchedEngines: responses.map(item => item.engine),
  engineErrors,
  candidateCount: byUrl.size,
  selectedCount: selected.length,
  questions: [...new Set(questions)].slice(0, 10),
  relatedSearches: [...new Set(relatedSearches)].slice(0, 10)
};

return selected.map((source, index) => ({
  json: {
    sourceId: 'S' + String(index + 1).padStart(2, '0'),
    ...source,
    researchContext
  }
}));

const source = $('Loop Over Sources').item.json;
const response = ($input.first().json || {});
const markdown = typeof (response.data && response.data.markdown) === 'string' ? response.data.markdown.trim() : '';
const success = response.code === 0 && markdown.length > 0;

return [{
  json: {
    ...source,
    extractionStatus: success ? 'success' : 'failed',
    extractionMode: 'standard',
    extractedTitle: (response.data && response.data.title) || source.title,
    markdown: success ? markdown : '',
    excerpt: success ? markdown.replace(/\s+/g, ' ').slice(0, 2800) : '',
    extractionMessage: success ? '' : (response.msg || response.message || 'Reader returned no Markdown'),
    accessedAt: new Date().toISOString()
  }
}];

const source = $('Loop Over Sources').item.json;
const response = ($input.first().json || {});
const markdown = typeof (response.data && response.data.markdown) === 'string' ? response.data.markdown.trim() : '';
const success = response.code === 0 && markdown.length > 0;

return [{
  json: {
    ...source,
    extractionStatus: success ? 'success' : 'failed',
    extractionMode: 'browser-fallback',
    extractedTitle: (response.data && response.data.title) || source.title,
    markdown: success ? markdown : '',
    excerpt: success ? markdown.replace(/\s+/g, ' ').slice(0, 2800) : '',
    extractionMessage: success ? '' : (response.msg || response.message || 'Reader returned no Markdown'),
    accessedAt: new Date().toISOString()
  }
}];

const config = $('Set research config').first().json;
const items = $input.all().map(item => item.json);
const successful = items.filter(item => item.extractionStatus === 'success');
const failed = items.filter(item => item.extractionStatus !== 'success');
const context = (items[0] && items[0].researchContext) || {};

const manifest = successful.map(item => ({
  sourceId: item.sourceId,
  title: item.extractedTitle || item.title,
  url: item.url,
  hostname: item.hostname,
  searchEngines: item.engines,
  bestSearchPosition: item.bestPosition,
  extractionMode: item.extractionMode,
  accessedAt: item.accessedAt,
  searchSnippet: item.snippet,
  excerpt: item.excerpt
}));

const sourceSections = manifest.map(source => [
  '## [' + source.sourceId + '] ' + source.title,
  '',
  '- URL: ' + source.url,
  '- Found via: ' + source.searchEngines.join(', '),
  '- Best observed position: ' + source.bestSearchPosition,
  '- Extraction mode: ' + source.extractionMode,
  '- Accessed: ' + source.accessedAt,
  '',
  source.excerpt
].join('\n'));

const questionSection = (context.questions && context.questions.length)
  ? ['## Questions surfaced by the search results', '', ...context.questions.map(q => '- ' + q)].join('\n')
  : '';

const relatedSection = (context.relatedSearches && context.relatedSearches.length)
  ? ['## Related searches', '', ...context.relatedSearches.map(q => '- ' + q)].join('\n')
  : '';

const failureSection = failed.length
  ? ['## Manual review queue', '', ...failed.map(item => '- [' + item.sourceId + '] ' + item.url + ': ' + item.extractionMessage)].join('\n')
  : '';

const coverage = {
  requestedSources: Number(config.maxSources || 4),
  selectedSources: items.length,
  extractedSources: successful.length,
  failedSources: failed.length,
  uniqueDomains: new Set(items.map(item => item.hostname)).size,
  standardExtractions: successful.filter(item => item.extractionMode === 'standard').length,
  browserFallbackExtractions: successful.filter(item => item.extractionMode === 'browser-fallback').length
};

const researchPackMarkdown = [
  '# Source-diverse web evidence pack',
  '',
  'Research question: ' + (context.query || config.query),
  'Generated: ' + new Date().toISOString(),
  'Sources extracted: ' + successful.length + ' of ' + items.length,
  'Unique domains: ' + coverage.uniqueDomains,
  '',
  'This pack preserves source URLs and extraction metadata. It does not verify that every source or claim is correct. Review quotations and time-sensitive claims before use.',
  '',
  questionSection,
  relatedSection,
  ...sourceSections,
  failureSection
].filter(Boolean).join('\n\n');

return [{
  json: {
    query: context.query || config.query,
    generatedAt: new Date().toISOString(),
    coverage,
    engineErrors: context.engineErrors || [],
    questions: context.questions || [],
    relatedSearches: context.relatedSearches || [],
    sourceManifest: manifest,
    manualReviewQueue: failed.map(item => ({
      sourceId: item.sourceId,
      title: item.title,
      url: item.url,
      message: item.extractionMessage
    })),
    researchPackMarkdown
  }
}];
